mapper.select:
select migration_record_id as migrationRecordId, source_record_id as sourceRecordId, fields_json as fieldsJson, merge_status as mergeStatus, target_table as targetTable, target_id as targetId, merge_message as mergeMessage, imported_at as importedAt from app_feishu_migration_record where source_table_id = #{sourceTableId}
and merge_status = #{mergeStatus}
order by migration_record_id desc
